BEGIN; ALTER TABLE app_audit_log ADD COLUMN IF NOT EXISTS prev_hash TEXT NULL; ALTER TABLE app_audit_log ADD COLUMN IF NOT EXISTS event_hash TEXT NULL; ALTER TABLE app_audit_log ADD COLUMN IF NOT EXISTS hash_version TEXT NOT NULL DEFAULT 'v1'; ALTER TABLE app_audit_log ADD COLUMN IF NOT EXISTS correlacion_id TEXT NULL; CREATE INDEX IF NOT EXISTS idx_audit_log_hash ON app_audit_log( id, event_hash) ; CREATE INDEX IF NOT EXISTS idx_audit_log_correlacion ON app_audit_log( correlacion_id) ; ALTER TABLE expediente_versiones ADD COLUMN IF NOT EXISTS correlacion_id TEXT NULL; ALTER TABLE expediente_versiones ADD COLUMN IF NOT EXISTS mfa_verificado BOOLEAN NOT NULL DEFAULT false; ALTER TABLE expediente_versiones ADD COLUMN IF NOT EXISTS mfa_step BIGINT NULL; ALTER TABLE expediente_versiones ADD COLUMN IF NOT EXISTS aprobacion_id BIGINT NULL REFERENCES app_solicitudes_acceso( id) ON DELETE SET NULL; ALTER TABLE expediente_versiones ADD COLUMN IF NOT EXISTS record_hash TEXT NULL; CREATE TABLE IF NOT EXISTS app_integridad_verificaciones( id BIGSERIAL PRIMARY KEY, ejecutado_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, ejecutado_por BIGINT NULL REFERENCES app_users( id) ON DELETE SET NULL, alcance TEXT NOT NULL DEFAULT 'completa', estado TEXT NOT NULL, total_eventos BIGINT NOT NULL DEFAULT 0, eventos_validos BIGINT NOT NULL DEFAULT 0, eventos_inconsistentes BIGINT NOT NULL DEFAULT 0, primer_evento_inconsistente_id BIGINT NULL, total_versiones BIGINT NOT NULL DEFAULT 0, versiones_inconsistentes BIGINT NOT NULL DEFAULT 0, total_documentos BIGINT NOT NULL DEFAULT 0, documentos_validos BIGINT NOT NULL DEFAULT 0, documentos_inconsistentes BIGINT NOT NULL DEFAULT 0, detalles_json JSONB NOT NULL DEFAULT '{}'::jsonb) ; CREATE INDEX IF NOT EXISTS idx_integridad_verif_fecha ON app_integridad_verificaciones( ejecutado_at DESC) ; ALTER TABLE app_politicas_seguridad ADD COLUMN IF NOT EXISTS require_dual_approval_restore BOOLEAN NOT NULL DEFAULT false; ALTER TABLE app_solicitudes_acceso A